function graphFromSequence(activities:Activity[]):Flowchart{const start=`start-${uid()}`,end=`end-${uid()}`;const actionNodes=activities.map(activity=>({id:`node-${uid()}`,kind:'action' as const,label:String(activity.label??activity.type),activity}));const nodes:FlowNode[]=[{id:start,kind:'start',label:'Start'},...actionNodes,{id:end,kind:'end',label:'End'}];const transitions:FlowTransition[]=[];for(let index=0;index<nodes.length-1;index++)transitions.push({from:nodes[index].id,to:nodes[index+1].id,when:'always'});return{start,nodes,transitions}}
function sequenceFromGraph(graph:Flowchart):Activity[]|null{if(graph.nodes.some(node=>node.kind==='decision'))return null;const map=new Map(graph.nodes.map(node=>[node.id,node]));const actions:Activity[]=[];const visited=new Set<string>();let current:string|null=graph.start;while(current){if(visited.has(current))return null;visited.add(current);const node=map.get(current);if(!node)return null;if(node.kind==='action'&&node.activity)actions.push(node.activity);if(node.kind==='end')break;current=graph.transitions.find(edge=>edge.from===node.id)?.to??null}return visited.size===graph.nodes.length?actions:null}
function machineFromSequence(activities:Activity[]):StateMachine{return{initial:'state-start',states:[{id:'state-start',label:'Start',activities},{id:'state-end',label:'Complete',final:true,activities:[]}],transitions:[{from:'state-start',to:'state-end'}]}}
function sequenceFromMachine(machine:StateMachine):Activity[]|null{const map=new Map(machine.states.map(state=>[state.id,state]));const result:Activity[]=[];const seen=new Set<string>();let current:string|null=machine.initial;while(current){if(seen.has(current))return null;seen.add(current);const state=map.get(current);if(!state)return null;result.push(...state.activities);if(state.final)break;const edges=machine.transitions.filter(edge=>edge.from===current);if(edges.length!==1||edges[0].condition)return null;current=edges[0].to}return seen.size===machine.states.length?result:null}
function draftPreview(workflow:Workflow):{summary:string;items:{id:string;label:string}[]}{if(workflow.executionModel==='flowchart'&&workflow.flowchart)return{summary:`${workflow.flowchart.nodes.length} flowchart nodes`,items:workflow.flowchart.nodes.map(node=>({id:node.id,label:`${node.kind.toUpperCase()} · ${node.label??node.id}${node.activity?` · ${labelFor(node.activity.type)}`:''}`}))};if(workflow.executionModel==='state_machine'&&workflow.stateMachine)return{summary:`${workflow.stateMachine.states.length} states · ${workflow.stateMachine.transitions.length} transitions`,items:workflow.stateMachine.states.map(state=>({id:state.id,label:`${state.final?'FINAL · ':''}${state.label} · ${state.activities.length} activities`}))};return{summary:`${workflow.activities.length} activities`,items:workflow.activities.map(activity=>({id:activity.id,label:labelFor(activity.type)}))}}
