  function dismissAiDialog(){const draftId=activeAiDraftId.current;activeAiDraftId.current=null;aiRequestGeneration.current++;setShowAi(false);setAiBusy(false);if(draftId)void cancelAiDraft(draftId).catch(error=>setNotice(`Could not stop the AI request: ${String(error)}`))}
  async function refreshAiModels(){const request=++aiRequestGeneration.current;setAiBusy(true);setAiError('');setAiModels([]);setAiConnectionState({status:'checking'});const started=performance.now();try{const models=await listAiModels(aiConfig());if(request!==aiRequestGeneration.current)return;const durationMs=Math.round(performance.now()-started);setAiModels(models);if(models.length&&!aiModel.trim())setAiModel(models[0]);if(models.length)setAiConnectionState({status:'connected',modelCount:models.length,durationMs});else{setAiConnectionState({status:'empty',durationMs});setAiError('The endpoint responded but did not list models. You can enter an enabled model ID manually.')}}catch(e){if(request!==aiRequestGeneration.current)return;const message=e instanceof Error?e.message:String(e);setAiConnectionState({status:'catalog-failed',message});setAiError(`Could not list models: ${message}. You can still enter a model ID and try generation.`)}finally{if(request===aiRequestGeneration.current)setAiBusy(false)}}
  function useAiConnection(profile:AiConnectionProfile){setAiConnectionId(profile.id);setAiConnectionName(profile.name);setAiProvider(profile.provider);setAiBaseUrl(profile.baseUrl);setAiCredentialService(profile.credentialService??'');setAiCredentialUsername(profile.credentialUsername??'');setAiModel(profile.model??'');setAiModels([]);setAiDraft(null);setAiError('');setAiConnectionState({status:'idle'})}
  async function saveAiConnectionProfile(){setAiBusy(true);setAiError('');try{const saved=await saveAiConnection({id:aiConnectionId||undefined,name:aiConnectionName,provider:aiProvider,baseUrl:aiBaseUrl,model:aiModel,credentialService:aiCredentialService,credentialUsername:aiCredentialUsername});setAiConnections(current=>[...current.filter(profile=>profile.id!==saved.id),saved].sort((a,b)=>a.name.localeCompare(b.name)));setAiConnectionId(saved.id);setAiConnectionName(saved.name);setNotice('AI connection saved locally; credential values remain in the OS vault.')}catch(e){setAiError(String(e))}finally{setAiBusy(false)}}
