  async function saveAiCredential(){setAiBusy(true);setAiError('');try{await storeAiCredential(aiCredentialService,aiCredentialUsername,aiCredentialSecret);setAiCredentialSecret('');setNotice('AI credential stored in the operating-system vault');}catch(e){setAiError(String(e))}finally{setAiBusy(false)}}
  async function openAiDraft(initialMode?:'sequence'|'flowchart'|'state_machine'){const request=++aiRequestGeneration.current;setShowAi(true);setAiError('');setAiDraft(null);setAiDraftMode(initialMode??workflow.executionModel??'sequence');if(browserMode){setAiError('AI provider connections are available in the desktop app only.');return}try{const [providers,profiles]=await Promise.all([listAiProviders(),listAiConnections()]);if(request!==aiRequestGeneration.current)return;setAiProviders(providers);setAiConnections(profiles);await refreshAiModels()}catch(e){if(request===aiRequestGeneration.current)setAiError(String(e))}}
